// A minimal re-implementation of the Python `bidict` behavior needed here:
// insertion-ordered, bidirectional (values are unique), with `clear`,
// item assignment, and Python-faithful repr output.
import { pyRepr } from './pyformat.mjs';

export class ValueDuplicationError extends Error {
  constructor(value) {
    super(pyRepr(value));
    this.name = 'bidict.ValueDuplicationError';
    this.value = value;
  }
}

export class Bidict {
  constructor(entries) {
    this._fwd = Object.create(null); // key -> value
    this._inv = new globalThis.Map(); // value -> key (internal bookkeeping)
    this._order = []; // insertion order of keys
    if (entries) {
      for (const [k, v] of entries) {
        this._dedupAndPut(k, v);
      }
    }
  }

  _dedupAndPut(key, value) {
    // Strict bidict: a value may not be associated with a different key.
    if (this._inv.has(value) && this._inv.get(value) !== key) {
      throw new ValueDuplicationError(value);
    }
    if (Object.prototype.hasOwnProperty.call(this._fwd, key)) {
      // Overwrite: drop the old value's reverse link, keep key position.
      const oldValue = this._fwd[key];
      if (oldValue !== value) {
        this._inv.delete(oldValue);
      }
    } else {
      this._order.push(key);
    }
    this._fwd[key] = value;
    this._inv.set(value, key);
  }

  set(key, value) {
    this._dedupAndPut(key, value);
  }

  clear() {
    this._fwd = Object.create(null);
    this._inv.clear();
    this._order = [];
  }

  get size() {
    return this._order.length;
  }

  toString() {
    if (this._order.length === 0) return 'bidict()';
    const parts = this._order.map(
      (k) => `${pyRepr(k)}: ${pyRepr(this._fwd[k])}`
    );
    return `bidict({${parts.join(', ')}})`;
  }
}

