// Minimal argparse-compatible parser matching Python's argparse behavior
// for the exact argument spec used by test16.py.

const PROG = 'test16_executable';

/** Mirror Python's int(str): optional surrounding whitespace, sign, digits. */
function parseIntType(raw) {
  const trimmed = raw.trim();
  if (!/^[+-]?\d+$/.test(trimmed)) {
    return null;
  }
  return parseInt(trimmed, 10);
}

function usage() {
  return `usage: ${PROG} [-h] --k1 K1 --v1 V1 --k2 K2 --v2 V2 --k3 K3 --v3 V3`;
}

function fail(message) {
  process.stderr.write(usage() + '\n');
  process.stderr.write(`${PROG}: error: ${message}\n`);
  process.exit(2);
}

function printHelpAndExit(spec) {
  const lines = [usage(), '', 'options:'];
  lines.push('  -h, --help  show this help message and exit');
  for (const arg of spec) {
    const metavar = arg.name.slice(2).toUpperCase();
    lines.push(`  ${arg.name} ${metavar}`);
  }
  process.stdout.write(lines.join('\n') + '\n');
  process.exit(0);
}

/**
 * Parse argv (process.argv.slice(2)) against the spec:
 *   [{ name: '--k1', type: 'str', required: true }, ...]
 * Returns an object keyed by the argument name without the leading '--'.
 */
export function parseArgs(argv, spec) {
  const result = {};
  const seen = new Set();
  const unrecognized = [];

  let i = 0;
  while (i < argv.length) {
    const token = argv[i];
    if (token === '-h' || token === '--help') {
      printHelpAndExit(spec);
    }
    const arg = spec.find((a) => a.name === token);
    if (!arg) {
      unrecognized.push(token);
      i += 1;
      continue;
    }
    if (i + 1 >= argv.length) {
      fail(`argument ${arg.name}: expected one argument`);
    }
    const raw = argv[i + 1];
    let value;
    if (arg.type === 'int') {
      value = parseIntType(raw);
      if (value === null) {
        fail(`argument ${arg.name}: invalid int value: '${raw}'`);
      }
    } else {
      value = raw;
    }
    result[arg.name.slice(2)] = value;
    seen.add(arg.name);
    i += 2;
  }

  if (unrecognized.length > 0) {
    fail(`unrecognized arguments: ${unrecognized.join(' ')}`);
  }

  const missing = spec
    .filter((a) => a.required && !seen.has(a.name))
    .map((a) => a.name);
  if (missing.length > 0) {
    fail(`the following arguments are required: ${missing.join(', ')}`);
  }

  return result;
}

