// Entry point mirroring /workspace/dataset/bidict/test16.py
import { parseArgs } from './lib/argparse.mjs';
import { Bidict, ValueDuplicationError } from './lib/bidict.mjs';

const args = parseArgs(process.argv.slice(2), [
  { name: '--k1', type: 'str', required: true },
  { name: '--v1', type: 'int', required: true },
  { name: '--k2', type: 'str', required: true },
  { name: '--v2', type: 'int', required: true },
  { name: '--k3', type: 'str', required: true },
  { name: '--v3', type: 'int', required: true },
]);

try {
  // 使用clear方法清空字典
  const b = new Bidict([
    [args.k1, args.v1],
    [args.k2, args.v2],
  ]);
  console.log(String(b));
  b.set(args.k3, args.v3);
  console.log(String(b));
  b.clear();
  console.log(String(b));

  // 重新填充
  b.set('new', 100);
  console.log(String(b));
} catch (err) {
  if (err instanceof ValueDuplicationError) {
    process.stderr.write(`bidict.ValueDuplicationError: ${err.message}\n`);
    process.exit(1);
  }
  throw err;
}

